<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ApiClient, errorMessage } from '../api'
import { dateTime, jobLabels, localDateTime } from '../domain'
import type { Job, NoticeSink, Session } from '../types'
interface GenerationLimits { shop_id: string; requests_per_minute: number; daily_request_limit: number; daily_token_limit: number; version: number; updated_at: string; global_max_concurrent: 1; request_reservation_tokens: 100000 }
interface GenerationUsage { limits: GenerationLimits; date_utc: string; requests_today: number; charged_tokens_today: number; unknown_requests_today: number; pending_requests_today: number; enforcement: string }
interface SpeechSchedule { id: string; shop_id: string; session_id: string; job_id: string; run_at: string; expires_at: string; status: 'scheduled' | 'dispatching' | 'sent' | 'failed' | 'cancelled' | 'delivery_unknown'; reason: string; error_code: string; created_at: string; updated_at: string }
const props = defineProps<{ api: ApiClient; shopId: string; jobs: Job[]; sessions: Session[]; notify: NoticeSink; reload: () => Promise<void> }>()
const tab = ref('schedules'), schedules = ref<SpeechSchedule[]>([]), usage = ref<GenerationUsage | null>(null), loading = ref(false), error = ref(''), operationError = ref(''), busy = ref(''), jobId = ref('')
const policyDirty = ref(false)
const limitsDirty = ref(false), confirmed = ref(false), runAt = ref(''), endAt = ref(''), priority = ref(50), jobExpires = ref('')
const limitsForm = reactive({ minute: 10, requests: 0, tokens: 0 })
const selected = computed(() => props.jobs.find(job => job.id === jobId.value))
const eligible = computed(() => props.jobs.filter(job => !['sent', 'sending', 'cancelled', 'delivery_unknown'].includes(job.status)))
const schedulable = computed(() => selected.value && ['approved', 'queued', 'synthesizing', 'ready'].includes(selected.value.status))
const scheduleLabels = { scheduled: '等待计划时间', dispatching: '正在派发', sent: '上游已接收', failed: '计划失败', cancelled: '已取消', delivery_unknown: '结果不明' }
let disposed = false
watch(eligible, values => { if (!values.some(j => j.id === jobId.value)) jobId.value = values[0]?.id ?? '' }, { immediate: true })
watch(jobId, () => { policyDirty.value = false })
watch(selected, job => { if (!policyDirty.value) { priority.value = job?.priority ?? 50; jobExpires.value = localDateTime(job?.expires_at ?? null) } }, { immediate: true })
function suggestTimes() { const start = Math.ceil((Date.now() + 300_000) / 60_000) * 60_000; runAt.value = localDateTime(new Date(start).toISOString()); endAt.value = localDateTime(new Date(start + 60_000).toISOString()); confirmed.value = false }
suggestTimes()
async function load() {
  if (loading.value) return; loading.value = true; error.value = ''
  const results = await Promise.allSettled([props.api.request<SpeechSchedule[]>('/schedules', { query: { shop_id: props.shopId } }), props.api.request<GenerationUsage>('/generation/usage', { query: { shop_id: props.shopId } })])
  if (disposed) return
  results.forEach((result, index) => { if (result.status === 'rejected') error.value += (error.value ? '；' : '') + errorMessage(result.reason); else if (index === 0) schedules.value = result.value as SpeechSchedule[]; else { usage.value = result.value as GenerationUsage; if (!limitsDirty.value) Object.assign(limitsForm, { minute: usage.value.limits.requests_per_minute, requests: usage.value.limits.daily_request_limit, tokens: usage.value.limits.daily_token_limit }) } })
  loading.value = false
}
onMounted(load)
const timer = window.setInterval(() => { if (document.visibilityState !== 'hidden') void load() }, 5000)
onBeforeUnmount(() => { disposed = true; window.clearInterval(timer) })
async function savePolicy() {
  if (!selected.value || busy.value) return; operationError.value = ''
  try { if (!Number.isInteger(Number(priority.value)) || Number(priority.value) < 0 || Number(priority.value) > 100) throw new Error('优先级应为 0–100 的整数。'); const expires = jobExpires.value ? new Date(jobExpires.value).toISOString() : null; if (expires && Date.parse(expires) <= Date.now()) throw new Error('截止时间必须在未来；已过期任务不能通过延长时间复活。'); busy.value = 'policy'; await props.api.request('/jobs/' + selected.value.id + '/dispatch-policy', { method: 'PUT', body: { shop_id: props.shopId, priority: Number(priority.value), expires_at: expires } }); policyDirty.value = false; await props.reload(); props.notify('任务优先级与截止时间已更新，不改变审核要求。') } catch (cause) { operationError.value = errorMessage(cause) } finally { busy.value = '' }
}
async function createSchedule() {
  if (!selected.value || !schedulable.value || !confirmed.value || busy.value) return; operationError.value = ''
  try { const start = Date.parse(runAt.value), end = Date.parse(endAt.value); if (!Number.isFinite(start) || !Number.isFinite(end) || start <= Date.now() || start > Date.now() + 7 * 86400_000 || end <= start || end > start + 3600_000) throw new Error('派发时间需在未来 7 天内，截止时间需晚于派发时间且最多延后 1 小时。'); busy.value = 'schedule'; await props.api.request('/jobs/' + selected.value.id + '/schedule', { method: 'POST', body: { shop_id: props.shopId, run_at: new Date(start).toISOString(), expires_at: new Date(end).toISOString() } }); confirmed.value = false; await load(); await props.reload(); props.notify('单次计划已保存。到期仍须通过版本、审核、音频和独立输出在线检查。') } catch (cause) { operationError.value = errorMessage(cause) } finally { busy.value = '' }
}
async function cancelSchedule(schedule: SpeechSchedule) { if (busy.value || schedule.status !== 'scheduled') return; busy.value = schedule.id; operationError.value = ''; try { await props.api.request('/schedules/' + schedule.id + '/cancel', { method: 'POST', body: { shop_id: props.shopId } }); await load(); props.notify('尚未派发的计划已取消，已审核草稿和音频仍保留。') } catch (cause) { operationError.value = errorMessage(cause) } finally { busy.value = '' } }
async function saveLimits() { if (!usage.value || busy.value) return; operationError.value = ''; try { const minute = Number(limitsForm.minute), requests = Number(limitsForm.requests), tokens = Number(limitsForm.tokens); if (![minute, requests, tokens].every(Number.isInteger) || minute < 1 || minute > 60 || requests < 0 || requests > 100000 || tokens < 0 || tokens > 1000000000) throw new Error('请按字段范围填写整数限额。'); busy.value = 'limits'; await props.api.request('/generation/limits', { method: 'PUT', body: { shop_id: props.shopId, requests_per_minute: minute, daily_request_limit: requests, daily_token_limit: tokens, version: usage.value.limits.version } }); limitsDirty.value = false; await load(); props.notify('DeepSeek 本地限额已更新，按 UTC 自然日计数。') } catch (cause) { operationError.value = errorMessage(cause) } finally { busy.value = '' } }
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">SCHEDULE & LIMITS</div><h1>调度与额度</h1><p>只安排已审核的话术，给生成请求设置明确上限。</p></div><button class="button secondary" :disabled="loading" @click="load">刷新状态</button></div><div class="integration-tabs segmented"><button :class="{ active: tab === 'schedules' }" @click="tab = 'schedules'">单次计划与优先级</button><button :class="{ active: tab === 'limits' }" @click="tab = 'limits'">生成限额</button></div><div v-if="error || operationError" class="alert error" role="alert">{{ operationError || error }}</div>
  <div v-show="tab === 'schedules'"><div class="settings-grid"><section class="panel padded"><form class="form-stack" @submit.prevent="savePolicy" @input="policyDirty = true"><h2>任务派发策略</h2><label>未发送任务<select v-model="jobId" required><option value="">先在工作台创建话术</option><option v-for="job in eligible" :key="job.id" :value="job.id">{{ jobLabels[job.status] }} · {{ job.text.slice(0, 42) || job.id }}</option></select></label><p v-if="selected" class="hint">{{ sessions.find(s => s.id === selected?.session_id)?.title }} · {{ selected.text }}</p><label>合成优先级（0–100）<input v-model="priority" type="number" min="0" max="100" step="1" required /><small>数字越大越先领取；不会强行打断正在合成的任务。</small></label><label>任务截止时间<input v-model="jobExpires" type="datetime-local" /><small>留空表示无额外截止时间，商品等事实有效期仍然生效。</small></label><button class="button secondary" :disabled="!!busy || !selected">{{ busy === 'policy' ? '保存中…' : '保存任务策略' }}</button></form></section><section class="panel padded"><form class="form-stack" @submit.prevent="createSchedule"><h2>安排一次派发</h2><p class="hint">使用左侧任务。仅已批准、排队合成、正在合成或音频就绪的话术可以安排；不会自动审核或自动生成；音频尚未就绪时须先配置本地语音服务。</p><label>计划派发时间<input v-model="runAt" type="datetime-local" required @input="confirmed = false" /></label><label>计划最晚截止<input v-model="endAt" type="datetime-local" required @input="confirmed = false" /><small>建议派发时间后 60 秒；音频没及时就绪则超时失败。</small></label><button type="button" class="inline-button" @click="suggestTimes">设为约 5 分钟后，保留 60 秒窗口</button><label class="checkbox-row"><input v-model="confirmed" type="checkbox" />已核对话术，并会保持本场次独立输出端在线</label><button class="button primary" :disabled="!!busy || !schedulable || !confirmed">{{ busy === 'schedule' ? '安排中…' : '保存单次派发计划' }}</button><p v-if="selected && !schedulable" class="hint">这条话术尚未通过审核或状态不允许安排，请先到工作台处理。</p></form></section></div><p class="page-note">仅独立输出端可接收自动派发。离线、版本过时或结果不明时不会自动重试；重启后错过时间的计划不会突然补播。取消已在派发的内容请使用场次接管。</p>
  <section class="panel events-panel"><div class="panel-title"><h2>已保存计划 · 最近 100 条</h2></div><div v-if="!schedules.length" class="empty-state compact"><h3>暂无派发计划</h3><p>先批准一条话术，再设置未来时间。</p></div><div v-else class="table-scroll"><table><thead><tr><th>任务 / 场次</th><th>派发窗口</th><th>状态 / 原因</th><th>操作</th></tr></thead><tbody><tr v-for="schedule in schedules" :key="schedule.id"><td><strong>{{ jobs.find(j => j.id === schedule.job_id)?.text.slice(0, 45) || schedule.job_id }}</strong><div class="secondary-line">{{ sessions.find(s => s.id === schedule.session_id)?.title || schedule.session_id }}</div></td><td>{{ dateTime(schedule.run_at) }}<div class="secondary-line">截止 {{ dateTime(schedule.expires_at) }}</div></td><td><span class="badge" :class="schedule.status === 'sent' ? 'success' : ['failed', 'delivery_unknown'].includes(schedule.status) ? 'danger' : 'neutral'">{{ scheduleLabels[schedule.status] }}</span><div v-if="schedule.reason || schedule.error_code" class="secondary-line">{{ schedule.reason || schedule.error_code }}</div></td><td><button v-if="schedule.status === 'scheduled'" class="button ghost small danger-text" :disabled="!!busy" @click="cancelSchedule(schedule)">取消计划</button><span v-else class="muted small-text">{{ schedule.status === 'dispatching' || schedule.status === 'delivery_unknown' ? '请到场次接管' : '—' }}</span></td></tr></tbody></table></div></section></div>
  <div v-show="tab === 'limits'" class="settings-grid"><section class="panel padded"><form class="form-stack" @submit.prevent="saveLimits" @input="limitsDirty = true"><h2>当前店铺的 DeepSeek 限额</h2><label>每分钟请求数<input v-model="limitsForm.minute" type="number" min="1" max="60" step="1" required /></label><label>每日请求数上限<input v-model="limitsForm.requests" type="number" min="0" max="100000" step="1" required /><small>0 表示不限制日请求数。</small></label><label>每日 token 上限<input v-model="limitsForm.tokens" type="number" min="0" max="1000000000" step="1" required /><small>0 表示不限制日 token；每次先保守预留 100,000 tokens，余额不足会拒绝。</small></label><button class="button primary" :disabled="!!busy || !usage">{{ busy === 'limits' ? '保存中…' : '保存生成限额' }}</button></form></section><aside class="panel padded"><h2>今日额度状态</h2><template v-if="usage"><p class="hint">UTC 日期 {{ usage.date_utc }} · 全局最多 {{ usage.limits.global_max_concurrent }} 个生成流程在途</p><dl class="diagnostics"><div><dt>已记录请求</dt><dd>{{ usage.requests_today }}</dd></div><div><dt>已占用 / 结算 tokens</dt><dd>{{ usage.charged_tokens_today.toLocaleString() }}</dd></div><div><dt>用量未知请求</dt><dd>{{ usage.unknown_requests_today }}</dd></div><div><dt>在途请求</dt><dd>{{ usage.pending_requests_today }}</dd></div></dl><p class="page-note">{{ usage.enforcement }}</p></template><p v-else class="hint">尚未取得服务端额度记录。</p><div class="fine-divider" /><p class="hint">未知用量、取消或重启中的远程请求保留全部预留。100,000 tokens 是本地保守规则，不是精确分词数量或人民币账单上限；费用估算请到“用量与成本”。</p></aside></div>
</template>
